<script setup>
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import TeamMembers from './TeamMembers.vue';
import {savedTeam,savedTeamMe} from './team-settings-store.mjs';
import ReleaseMonthPicker from './ReleaseMonthPicker.vue';
import {myWorkSnapshot} from './my-work-store.mjs';
import {apiFetch,setActivePanelTab} from './store.js';
import {trackerLibrary,trackerError,trackerBusy,trackerNotice,trackerLoading,trackerAction,selectedTracker,selectedMilestone,loadTrackers,changeTracker} from './release-trackers-store.mjs';
import {milestoneKey,localDay,workingDays,effectiveCheckpoints,extractPlanDates,checkpointOptions,extractReleaseMonth,monthName,canIncludeSavedWork,trackerIssues} from './release-trackers.mjs';
import {myWorkRows,myWorkMetrics} from './my-work.mjs';
import {issuePackageSummaries} from './issue-packages-store.mjs';
import {filterMilestones} from './milestones.mjs';
defineProps({compact:Boolean});
const expanded=ref({});
watch(selectedTracker,id=>{if(id)expanded.value[id]=true;},{immediate:true});
watch(()=>trackerLibrary.value.trackers,items=>{if(!Object.keys(expanded.value).length&&items.length)expanded.value[items.find(t=>!t.archived)?.id||items[0].id]=true;},{immediate:true});
function includeSaved(){const saved=myWorkSnapshot.value;if(!saved)return;draft.value.milestones=draft.value.milestones.filter(m=>milestoneKey(m.config)!==milestoneKey(saved.config));draft.value.milestones.push({config:{...saved.config},snapshot:saved});}
const planFilename=ref(''),planNotice=ref(''),suggestedVersions=ref([]);
const draft=ref(null),showArchived=ref(false),repo=ref('rancher/rancher'),search=ref(''),found=ref([]),lookupBusy=ref(false),lookupError=ref(''),sourceText=ref(''),proposals=ref([]),importError=ref(''),importBusy=ref(false),importOpen=ref(false),deleteConfirm=ref(false),holidayText=ref(''),today=ref(localDay());
const tick=setInterval(()=>today.value=localDay(),60000);onBeforeUnmount(()=>clearInterval(tick));onMounted(loadTrackers);
const trackers=computed(()=>trackerLibrary.value.trackers.filter(t=>showArchived.value||!t.archived));
const choices=computed(()=>filterMilestones(found.value,search.value));
const uid=()=>crypto.randomUUID();
function edit(tracker){draft.value=tracker?JSON.parse(JSON.stringify(tracker)):{id:'',month:localDay().slice(0,7),name:monthName(localDay().slice(0,7)),notes:'',archived:false,milestones:[],checkpoints:[],holidays:[],planRepo:'rancher/rancher',issueLabel:'team/frameworks',teamMembers:[...savedTeam.value],teamMe:savedTeamMe.value};draft.value.teamMembers??=[...savedTeam.value];draft.value.teamMe??=savedTeamMe.value;repo.value=draft.value.planRepo||'rancher/rancher';draft.value.checkpoints=checkpointOptions(draft.value.checkpoints,!tracker);planFilename.value='';planNotice.value='';suggestedVersions.value=[...(draft.value.planVersions||[])];holidayText.value=draft.value.holidays.join('\n');sourceText.value='';proposals.value=[];importError.value='';importOpen.value=false;deleteConfirm.value=false;found.value=[];lookupError.value='';}
async function lookup(){lookupBusy.value=true;lookupError.value='';found.value=[];const value=repo.value.trim();try{const response=await apiFetch('/api/issue-radar/milestones',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({repo:value})});if(!response.ok)throw new Error(await response.text());const data=await response.json();if(repo.value.trim()===value)found.value=(data.milestones||[]).map(m=>({...m,repo:value.toLowerCase()}));if(!found.value.length)lookupError.value='No milestones found.';}catch(e){lookupError.value=e.message;}finally{lookupBusy.value=false;}}
function link(m){const config={repo:m.repo,milestone:m.number,scope:'all',user:'',label:''};if(draft.value.milestones.some(x=>milestoneKey(x.config)===milestoneKey(config)))return;draft.value.milestones.push({config,snapshot:{milestone:m}});}
function unlink(m){const key=milestoneKey(m.config);draft.value.milestones=draft.value.milestones.filter(x=>milestoneKey(x.config)!==key);draft.value.checkpoints=draft.value.checkpoints.filter(c=>c.milestone!==key);}
function addDate(){draft.value.checkpoints.push({id:uid(),name:'',date:'',milestone:'',tentative:false,source:''});}
async function save(){if(!draft.value.id)draft.value.checkpoints.forEach(c=>{if(!c.date)c.disabled=true;});draft.value.planRepo=repo.value.trim();draft.value.holidays=holidayText.value.split(/[\s,]+/).filter(Boolean);if(await changeTracker('save',draft.value))draft.value=null;}
async function remove(){if(await changeTracker('delete',draft.value)){if(selectedTracker.value===draft.value.id){selectedTracker.value='';selectedMilestone.value='';}draft.value=null;}}
function open(t,m){selectedTracker.value=t.id;selectedMilestone.value=m?milestoneKey(m.config):'';setActivePanelTab('my-work');}
function metrics(t){return myWorkMetrics(myWorkRows({issues:trackerIssues([t],t.id)},issuePackageSummaries.value));}
function next(t){return effectiveCheckpoints(t).find(c=>c.date>=today.value);}
function countdown(t){const n=next(t);if(!n)return effectiveCheckpoints(t).length?'All scheduled dates have passed':'Add your release dates';const days=workingDays(n.date,t.holidays,today.value);return n.date===today.value?`${n.name} is today`:`${days} working ${days===1?'day':'days'} until ${n.name.toLowerCase()}`;}
const displayDate=value=>new Date(`${value}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'});
function scanText(){
 if(!draft.value.id)draft.value.checkpoints=checkpointOptions(draft.value.checkpoints.filter(c=>!c.source),true);
 const result=draft.value.month?extractReleaseMonth(sourceText.value,draft.value.month):{checkpoints:extractPlanDates(sourceText.value),versions:[],mode:'all'};
 suggestedVersions.value=result.versions;draft.value.planVersions=[...result.versions];
 proposals.value=result.checkpoints.map(p=>{const old=draft.value.checkpoints.find(c=>!c.milestone&&((p.kind&&c.kind===p.kind)||c.name.toLowerCase()===p.name.toLowerCase()));return {...p,previous:old?.date||'',selected:!!old?.disabled||old?.date!==p.date};});
 importError.value=proposals.value.length?'':`No release checkpoints found${draft.value.month?' for '+monthName(draft.value.month):''}. Choose another month or add dates manually.`;
 planNotice.value=proposals.value.length?`${proposals.value.length} dates found${draft.value.month?' for '+monthName(draft.value.month):''}.${result.mode==='dates'?' No release headings found; review the dates matched by calendar month.':' Review them below before saving.'}`:'';
 if(!draft.value.id&&proposals.value.length){applyDates();}
}
function changeMonth(value){const previous=draft.value.month;draft.value.month=value;if(previous!==value){draft.value.planVersions=[];suggestedVersions.value=[];}if(!draft.value.name||draft.value.name===monthName(previous))draft.value.name=monthName(draft.value.month);if(sourceText.value&&!draft.value.id){draft.value.checkpoints=checkpointOptions(draft.value.checkpoints.filter(c=>!c.source),true);scanText();}}

async function importFile(event){const file=event.target.files?.[0];if(!file)return;const target=draft.value;importBusy.value=true;importError.value='';try{if(file.size>20*1024*1024)throw new Error('Choose a file smaller than 20 MB.');const {readPlanFile}=await import(/* @vite-ignore */ '/static/release_plan_import.js');const text=await readPlanFile(file);if(draft.value!==target)return;sourceText.value=text;planFilename.value=file.name;scanText();}catch(e){importError.value=e.message;}finally{importBusy.value=false;event.target.value='';}}
function applyDates(){for(const p of proposals.value.filter(x=>x.selected)){const old=draft.value.checkpoints.find(c=>((p.kind&&c.kind===p.kind)||c.name.toLowerCase()===p.name.trim().toLowerCase())&&c.milestone===p.milestone);const value={id:old?.id||uid(),kind:p.kind||old?.kind||'',name:p.name.trim(),date:p.date,milestone:p.milestone,tentative:p.tentative,source:p.source,disabled:false};if(old)Object.assign(old,value);else draft.value.checkpoints.push(value);}proposals.value=[];importOpen.value=false;}
</script>
<template>
<section class="rt" :class="{'rt-compact':compact}" aria-label="Release trackers">
 <header class="rt-heading"><div><span class="rt-eyebrow">Your command center</span><h2>Release trackers</h2></div><div class="rt-actions"><label class="rt-inline"><input type="checkbox" v-model="showArchived"/>Archived</label><button @click="loadTrackers" :disabled="trackerBusy||trackerLoading">{{trackerLoading?'Loading…':'Reload saved trackers'}}</button><button class="rt-primary" @click="edit()" :disabled="trackerBusy||!!draft">+ Add tracker</button></div></header>
 <p v-if="trackerNotice" role="status" class="rt-plan-notice">{{trackerNotice}}</p>
 <p v-if="trackerError" class="rt-error" role="alert">{{trackerError}}</p>
 <form v-if="draft" class="rt-editor" @submit.prevent="save">
 <fieldset :disabled="trackerBusy||importBusy"><legend>{{draft.id?'Edit release tracker':'New release tracker'}}</legend>
 <div v-if="!draft.id" class="rt-simple-create">
 <div class="rt-month-name"><label>Release month<ReleaseMonthPicker :model-value="draft.month" @update:model-value="changeMonth"/></label><label>Tracker name<input v-model="draft.name" required maxlength="120" placeholder="October 2026"/><small class="rt-muted">Suggested from your month. Rename it anytime.</small></label></div>
 <div class="rt-upload"><h3>Fill it from your release plan</h3><p class="rt-muted">Optional · Upload the whole planner. We’ll find the {{monthName(draft.month)}} release section and fill its key dates.</p><label class="rt-upload-button">{{importBusy?'Reading your plan…':planFilename?'Replace planning document':'Choose planning document'}}<input type="file" accept=".doc,.docx,.pdf,.txt,.md,.html,.mht,.mhtml" @change="importFile" :disabled="importBusy" aria-label="Upload planning document"/></label><small v-if="planFilename">{{planFilename}}</small><p class="rt-muted">Confluence Word export (.doc), DOCX, PDF, or text · stays on this device</p></div>
 <p v-if="importError" class="rt-error" role="status">{{importError}}</p><p v-if="planNotice" class="rt-plan-notice" role="status">{{planNotice}}</p>
 <div v-for="c in draft.checkpoints.filter(c=>c.date)" :key="c.id" class="rt-simple-date"><input type="checkbox" :checked="!c.disabled" @change="c.disabled=!$event.target.checked" :aria-label="`Include ${c.name}`"/><input v-model="c.name" aria-label="Date name"/><input type="date" v-model="c.date" :disabled="c.disabled" aria-label="Release date"/><small v-if="c.tentative" class="rt-muted">Tentative</small></div>

 <p v-if="!planFilename" class="rt-muted">No document handy? Create the tracker now and add dates later.</p>
 </div>
 <div v-if="canIncludeSavedWork(draft,myWorkSnapshot)" class="rt-saved-offer"><span>Saved My Work matches this release: {{myWorkSnapshot.milestone.title}}. Include its issues and plans.</span><button type="button" @click="includeSaved">Include existing My Work</button></div>
 <div class="rt-release-scope"><h3>Find work for this release</h3><p v-if="draft.planVersions?.length" class="rt-plan-notice">{{draft.planVersions.join(' · ')}} · All these milestones will be linked automatically.</p><div class="rt-lookup"><label>Release repository<input v-model="repo" placeholder="owner/repo" required/></label><label>Team or custom label<input v-model="draft.issueLabel" placeholder="team/frameworks" list="release-label-suggestions"/></label></div><datalist id="release-label-suggestions"><option value="team/frameworks"/></datalist><p class="rt-muted">Enter any GitHub label. Separate labels with commas to require all of them, or leave blank for all issues. Includes all owners across the release.</p></div>
 <TeamMembers v-model="draft.teamMembers" v-model:me="draft.teamMe" :disabled="trackerBusy"/>
 <details class="rt-more-options" :open="!!draft.id"><summary>{{draft.id?'Tracker details':'More options · milestones, custom dates & notes'}}</summary>
 <div class="rt-edit-title" v-if="draft.id"><label>Release month<ReleaseMonthPicker :model-value="draft.month" @update:model-value="changeMonth"/></label><label>Release name<input v-model="draft.name" required maxlength="120" placeholder="October 2026"/></label><label class="rt-inline"><input v-model="draft.archived" type="checkbox"/>Archived</label></div>
 <label>Notes<textarea v-model="draft.notes" maxlength="10000" rows="2" placeholder="Release context, links, or reminders…"/></label>
 <h3 v-if="draft.issues?.length">Individually added issues</h3><div v-for="issue in draft.issues||[]" :key="`${issue.repo}#${issue.number}`" class="rt-linked"><strong>#{{issue.number}} · {{issue.snapshot?.title}}<small>{{issue.repo}}</small></strong><button type="button" @click="draft.issues=draft.issues.filter(i=>i!==issue)">Remove from tracker</button></div>
 <div v-if="draft.planVersions?.length" class="rt-plan-notice"><strong>Planned versions · {{monthName(draft.month)}}</strong><p>{{draft.planVersions.join(' · ')}}</p><small>Saving automatically finds every listed GitHub milestone and pulls matching issues into this release.</small></div><p v-else class="rt-muted">No release-plan versions saved for this tracker. Import your plan to identify the versions for {{monthName(draft.month)||'this release'}}.</p>
 <h3>GitHub milestones</h3><p class="rt-muted">Link several milestones to this release. Entire milestone includes issues assigned outside your team; choose Assigned to me to narrow the list. Saving verifies them and prepares their package buckets.</p>
 <div class="rt-lookup"><label>Repository<input v-model="repo" placeholder="owner/repo" @input="found=[]"/></label><button type="button" @click="lookup" :disabled="lookupBusy">{{lookupBusy?'Looking up…':'Find milestones'}}</button><label>Search milestones<input v-model="search" placeholder="Version or milestone name"/></label></div>
 <p v-if="lookupError" role="alert" class="rt-error">{{lookupError}}</p>
 <div v-if="found.length" class="rt-results"><button v-for="m in choices" :key="m.number" type="button" @click="link(m)" :disabled="draft.milestones.some(x=>milestoneKey(x.config)===`${m.repo}#${m.number}`)">{{m.title}} <small>{{m.state}} · #{{m.number}}</small><span>+ Link</span></button><p v-if="!choices.length">No matching milestones.</p></div>
 <div v-for="m in draft.milestones" :key="milestoneKey(m.config)" class="rt-linked"><strong>{{m.snapshot?.milestone.title||`#${m.config.milestone}`}}<small>{{m.config.repo}}</small></strong><select v-model="m.config.scope" aria-label="Issue ownership"><option value="mine">Assigned to me</option><option value="all">Entire milestone</option><option value="unassigned">Unassigned</option></select><input v-if="m.config.scope==='mine'" v-model="m.config.user" placeholder="Signed-in GitHub user" aria-label="GitHub username"/><button type="button" @click="unlink(m)">Unlink</button></div>
 <div class="rt-heading rt-subheading"><h3>Release schedule</h3><div class="rt-actions"><button type="button" @click="importOpen=!importOpen">Import plan</button><button type="button" @click="addDate">+ Custom date</button></div></div>
 <p class="rt-muted">Check the dates you need for this release. Unchecking hides a date from timelines and countdowns, while keeping its saved details. Names and dates are editable.</p>
 <p class="rt-muted">Shared dates apply to every milestone. A milestone-specific date with the same name overrides its shared date.</p>
 <div v-if="importOpen" class="rt-import"><h3>Import and review dates</h3><p class="rt-muted">Paste your planner or choose a Confluence Word export, PDF, DOCX, or text file. Extraction stays on this device. Review suggestions before adding them.</p><input type="file" accept=".doc,.pdf,.docx,.txt,.md,.html,.mht,.mhtml" @change="importFile" :disabled="importBusy" aria-label="Import release plan"/><textarea v-model="sourceText" rows="5" placeholder="Code freeze: 16 Oct 2026&#10;Charts QA sign-off: 22 Oct 2026"/><button type="button" @click="scanText" :disabled="importBusy||!sourceText.trim()">{{importBusy?'Reading document…':'Find dates'}}</button><p v-if="importError" role="status" class="rt-error">{{importError}}</p>
 <div v-for="p in proposals" :key="p.id" class="rt-proposal"><div class="rt-date-row"><input type="checkbox" v-model="p.selected" :aria-label="`Include ${p.name}`"/><input v-model="p.name" aria-label="Proposed checkpoint name"/><input type="date" v-model="p.date" aria-label="Proposed date"/><select v-model="p.milestone" aria-label="Apply date to"><option value="">Shared release date</option><option v-for="m in draft.milestones" :value="milestoneKey(m.config)">{{m.snapshot?.milestone.title}}</option></select></div><small v-if="p.previous">Saved: {{p.previous}} → Proposed: {{p.date}}</small><details><summary>Source text</summary><pre>{{p.source}}</pre></details></div>
 <button v-if="proposals.length" type="button" class="rt-primary" @click="applyDates" :disabled="!proposals.some(p=>p.selected&&p.name.trim()&&p.date)||proposals.some(p=>p.selected&&(!p.name.trim()||!p.date))">Add selected dates to draft</button></div>
 <div v-for="c in draft.checkpoints" :key="c.id" class="rt-date-row rt-checkpoint" :class="{'rt-checkpoint-off':c.disabled}"><input type="checkbox" :checked="!c.disabled" @change="c.disabled=!$event.target.checked" :aria-label="`Include ${c.name||'custom checkpoint'} in schedule`"/><input v-model="c.name" required maxlength="120" placeholder="Checkpoint name" aria-label="Checkpoint name"/><input type="date" v-model="c.date" :required="!c.disabled && !!draft.id" :disabled="c.disabled" min="2000-01-01" max="2200-12-31" aria-label="Checkpoint date"/><select v-model="c.milestone" :disabled="c.disabled" aria-label="Checkpoint scope"><option value="">Shared release date</option><option v-for="m in draft.milestones" :value="milestoneKey(m.config)">{{m.snapshot?.milestone.title}}</option></select><label class="rt-inline"><input type="checkbox" v-model="c.tentative" :disabled="c.disabled"/>Tentative</label><button v-if="!c.kind" type="button" @click="draft.checkpoints=draft.checkpoints.filter(x=>x.id!==c.id)" :aria-label="`Remove ${c.name||'checkpoint'}`">Remove</button></div>
 <details class="rt-calendar"><summary>Working-day calendar</summary><p class="rt-muted">Monday–Friday, excluding today and including the deadline. Add your holidays as YYYY-MM-DD, one per line.</p><textarea v-model="holidayText" rows="3" aria-label="Excluded holidays" placeholder="2026-10-12"/></details>
 </details>
 <footer class="rt-actions"><button v-if="draft.id" type="button" @click="deleteConfirm=!deleteConfirm">Delete tracker</button><span class="rt-spacer"/><button type="button" @click="draft=null">Cancel</button><button class="rt-primary">{{trackerBusy?'Saving…':draft.id?'Save & load release issues':'Create & load release issues'}}</button></footer>
 <div v-if="deleteConfirm" class="rt-delete"><p>Delete this tracker and its schedule? Issue packages and buckets will remain.</p><button type="button" @click="remove">Delete tracker and schedule</button></div>
 </fieldset></form>
 <div v-if="!trackers.length&&!draft" class="rt-empty"><h3>A clear view of your next release.</h3><p>Link GitHub milestones, set your dates, and keep the work together.</p><button @click="edit()">Create your first tracker →</button></div>
 <div v-if="compact" class="rt-groups"><article v-for="t in trackers" :key="t.id" class="rt-group"><div class="rt-group-heading"><button class="rt-expand" :aria-expanded="!!expanded[t.id]" @click="expanded[t.id]=!expanded[t.id]"><span>{{expanded[t.id]?'▾':'▸'}}</span><strong>{{t.name}}</strong><span class="rt-muted">{{t.milestones.map(m=>m.snapshot?.milestone.title||'#'+m.config.milestone).join(' · ')||(t.issues?.length?`${t.issues.length} individually added issues`:'No issues added yet')}}</span><span class="rt-muted">{{metrics(t).open}} remaining</span><span class="rt-next">{{countdown(t)}}</span></button><button @click="edit(t)" :disabled="trackerBusy||!!draft" :aria-label="`Edit ${t.name}`">Edit</button><button :disabled="trackerBusy||(!t.milestones.length&&!t.issues?.length)" @click="changeTracker('refresh',t)" :aria-label="`Refresh ${t.name} issues`">{{trackerAction===`refresh:${t.id}`?'Refreshing…':'Refresh issues'}}</button></div><div v-if="expanded[t.id]" class="rt-group-body"><div v-if="!t.milestones.length&&!t.issues?.length" class="rt-empty"><h3>Add issues to {{t.name}}</h3><p>Choose individual issues in Issue Radar, or link a GitHub milestone to bring its issues into this release.</p><div class="rt-actions"><button class="rt-primary" @click="setActivePanelTab('issues')">Find issues in Issue Radar</button><button @click="edit(t)">Link a GitHub milestone</button><button v-if="canIncludeSavedWork(t,myWorkSnapshot)" :disabled="trackerBusy" @click="changeTracker('attach-saved-work',t)">Include existing My Work · {{myWorkSnapshot.milestone.title}}</button></div></div><slot v-else name="tracker" :tracker="t"/></div></article></div>
 <div v-else class="rt-grid"><article v-for="t in trackers" :key="t.id" class="rt-card" :class="{'rt-selected':selectedTracker===t.id,'rt-archived':t.archived}"><div class="rt-card-top"><button class="rt-title" @click="open(t)">{{t.name}} <small v-if="t.archived">Archived</small></button><button @click="edit(t)" :disabled="trackerBusy||!!draft" :aria-label="`Edit ${t.name}`">Edit</button></div><p class="rt-countdown">{{countdown(t)}}</p><div class="rt-milestones"><button v-for="m in t.milestones" :key="milestoneKey(m.config)" @click="open(t,m)" :title="m.config.repo">{{m.snapshot?.milestone.title||`#${m.config.milestone}`}}</button><span v-if="!t.milestones.length" class="rt-muted">No milestones linked yet</span></div>
 <div class="rt-timeline"><div v-for="c in effectiveCheckpoints(t).slice(0,8)" :key="c.id" :class="{'rt-past':c.date<today}" :title="c.milestone||'Shared release date'"><i/><strong>{{displayDate(c.date)}}</strong><span>{{c.name}}{{c.tentative?' · tentative':''}}</span><small v-if="c.milestone">{{t.milestones.find(m=>milestoneKey(m.config)===c.milestone)?.snapshot?.milestone.title}}</small></div></div><button v-if="effectiveCheckpoints(t).length>8" class="rt-muted" @click="edit(t)">View all {{effectiveCheckpoints(t).length}} dates</button>
 <div class="rt-health"><span><b>{{metrics(t).open}}</b> remaining</span><span><b>{{metrics(t).needsPlan}}</b> need plans</span><span><b>{{metrics(t).validated}}</b> validated</span></div><footer class="rt-card-footer"><button @click="open(t)">Open work →</button><button :disabled="trackerBusy||!!draft||(!t.milestones.length&&!t.issues?.length)" @click="changeTracker('refresh',t)">{{trackerAction===`refresh:${t.id}`?'Refreshing…':'Refresh issues'}}</button></footer><small class="rt-muted">{{t.milestones.length}} milestones<span v-if="t.milestones.some(m=>m.snapshot?.generatedAt)"> · Saved {{new Date(t.milestones.map(m=>m.snapshot?.generatedAt||'').filter(Boolean).sort()[0]).toLocaleString()}}</span></small></article></div>
</section>
</template>
